from collections import deque
def bfs(adj, s):
    seen, order, q = {s}, [s], deque([s])
    while q:
        x = q.popleft()
        for y in sorted(adj[x]):
            if y not in seen: seen.add(y); order.append(y); q.append(y)
    return order
def dfs(adj, s):
    seen, order = set(), []
    def go(x):
        seen.add(x); order.append(x)
        for y in sorted(adj[x]):
            if y not in seen: go(y)
    go(s); return order
